var n={PDF_PROTEGIDO:e=>`O arquivo "${e.nome??"selecionado"}" est\xE1 protegido por senha. Informe a senha para continuar. A senha \xE9 utilizada apenas neste navegador e n\xE3o \xE9 enviada a lugar algum.`,SENHA_INCORRETA:()=>"A senha informada n\xE3o confere. Verifique e tente novamente.",ARQUIVO_CORROMPIDO:e=>`N\xE3o foi poss\xEDvel ler "${e.nome??"o arquivo"}". O arquivo pode estar corrompido ou incompleto. Recomendamos abri-lo em um leitor de PDF e salv\xE1-lo novamente.`,TIPO_NAO_SUPORTADO:e=>`N\xE3o foi poss\xEDvel abrir "${e.nome??"o arquivo"}". Esta ferramenta aceita PDF. Documentos do Word e planilhas precisam ser exportados como PDF antes.`,FORMULARIO_XFA:()=>"Este documento utiliza formul\xE1rios XFA, formato que apenas o Adobe Acrobat l\xEA integralmente. \xC9 poss\xEDvel juntar e reordenar as p\xE1ginas, por\xE9m os campos do formul\xE1rio n\xE3o ser\xE3o preservados. Recomendamos imprimir o documento em PDF pelo Acrobat antes de prosseguir.",RESTRICOES_DE_EDICAO:()=>"Este documento possui restri\xE7\xF5es de edi\xE7\xE3o definidas pelo autor. Prosseguir remove essas restri\xE7\xF5es no arquivo gerado. Confirme que possui autoriza\xE7\xE3o para alter\xE1-lo.",MEMORIA_INSUFICIENTE:()=>"N\xE3o foi poss\xEDvel concluir: os arquivos selecionados s\xE3o grandes demais para a mem\xF3ria dispon\xEDvel nesta aba. Junte-os em duas etapas, ou feche outras abas e tente de novo. Como todo o trabalho acontece no seu computador, o limite aqui \xE9 a mem\xF3ria da m\xE1quina, n\xE3o uma regra nossa.",ARQUIVO_GRANDE_IOS:()=>"Arquivos deste tamanho costumam interromper o navegador em iPhone e iPad. Recomendamos utilizar um computador para este documento.",SEM_GANHO:()=>"Este documento j\xE1 est\xE1 otimizado: n\xE3o foi poss\xEDvel reduzir seu tamanho sem perda de qualidade. O arquivo original foi mantido.",PDF_ASSINADO:()=>"Este documento possui assinatura digital. Comprimir ou dividir invalida a assinatura. Recomendamos preparar o arquivo antes de assin\xE1-lo.",NAVEGADOR_SEM_SUPORTE:()=>"Seu navegador n\xE3o oferece os recursos necess\xE1rios para esta ferramenta. Atualize para uma vers\xE3o recente do Chrome, Firefox, Safari ou Edge.",REAMOSTRAGEM_INDISPONIVEL:()=>"A reamostragem de imagens n\xE3o \xE9 suportada neste navegador. A compress\xE3o estrutural continua dispon\xEDvel.",NENHUM_ARQUIVO:()=>"Selecione ao menos dois arquivos para juntar.",UM_ARQUIVO_SO:()=>"Com um \xFAnico arquivo n\xE3o h\xE1 o que juntar. Adicione ao menos mais um, ou use a ferramenta de organizar p\xE1ginas se o que voc\xEA precisa \xE9 reordenar as p\xE1ginas deste PDF.",TARJA_SEM_SELECAO:()=>"Marque ao menos uma \xE1rea antes de gerar o documento tarjado.",TARJA_NAO_VERIFICADA:()=>"A confer\xEAncia autom\xE1tica n\xE3o confirmou que o conte\xFAdo marcado saiu do arquivo, ent\xE3o o documento N\xC3O foi gerado. Isto \xE9 proposital: entregar um arquivo que talvez ainda contenha o dado seria pior do que n\xE3o entregar nada. Tente reduzir a sele\xE7\xE3o, ou marque a p\xE1gina inteira.",TARJA_GEOMETRIA_INCONSISTENTE:()=>"A confer\xEAncia interna encontrou diverg\xEAncia entre a \xE1rea marcada e a \xE1rea efetivamente coberta, e a opera\xE7\xE3o foi interrompida antes de gerar o arquivo. Recarregue a p\xE1gina e tente novamente.",RASTERIZACAO_INDISPONIVEL:()=>"Seu navegador n\xE3o oferece os recursos de imagem que o tarjamento exige. Atualize para uma vers\xE3o recente do Chrome, Firefox, Safari ou Edge. No Safari, \xE9 preciso a vers\xE3o 16.4 ou superior.",PAGINA_GRANDE_DEMAIS:()=>"Uma das p\xE1ginas marcadas \xE9 grande demais para ser processada nesta aba. Tente em um computador, ou reduza a resolu\xE7\xE3o na op\xE7\xE3o de qualidade.",FALHA_INESPERADA:()=>"N\xE3o foi poss\xEDvel concluir a opera\xE7\xE3o. Recarregue a p\xE1gina e tente novamente. Nenhum arquivo seu foi enviado a lugar algum."};function i(e,o={}){return n[e](o)}var r=class extends Error{codigo;contexto;constructor(o,a={}){super(i(o,a)),this.name="ErroFerramenta",this.codigo=o,this.contexto=a}};function s(e,o="FALHA_INESPERADA",a={}){return e instanceof r?e:e instanceof RangeError?new r("MEMORIA_INSUFICIENTE",a):new r(o,a)}export{i as a,r as b,s as c};
